var DATA = {"a": "Fluid: pulsatile blood flow", "b": "Structure: hyperelastic artery wall", "scheme": "Partitioned, implicit subiterations", "interface": "Velocity and traction continuity", "params": "Ta=310|Tb=310|k=0.2"};
console.log("Coupling: " + DATA.a + " <-> " + DATA.b);
console.log("Scheme: " + DATA.scheme + " | Interface: " + DATA.interface);
var p = {};
DATA.params.split("|").forEach(function (kv) {
  var parts = kv.split("=").map(function (s) { return s.trim(); });
  if (parts.length === 2) p[parts[0]] = parseFloat(parts[1]);
});
var Ta = p.Ta || 300, Tb = p.Tb || 350, k = p.k || 0.1, tol = 1e-6, it = 0;
// fixed-point coupling iteration: exchange interface values until convergence
while (it < 100) {
  var TaNew = Ta + k * (Tb - Ta), TbNew = Tb + k * (Ta - Tb);
  var d = Math.max(Math.abs(TaNew - Ta), Math.abs(TbNew - Tb));
  Ta = TaNew; Tb = TbNew; it++;
  if (d < tol) break;
}
console.log("Converged in " + it + " iterations: interface A=" + Ta.toFixed(4) + ", B=" + Tb.toFixed(4));
console.log("RESULT: coupled iteration converged — interface condition satisfied.");

